import React from 'react';

import ThreeDotsVertical from '@pohodnik/icons/svg/Controls/ThreeDotsVertical';
import clsx from 'clsx';

import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohBreadcrumbs from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohDropdown from '@ui-kit/Dropdown';
import PohContainer from '@ui-kit/layout/Container';
import PohList from '@ui-kit/List';

import { getEmptyScheduleItem } from '../@mappers/hikingSchedule.mapper';
import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingAccessGroupAsync } from '../@services/hikingRules.service';
import { deleteHikingSchedule, getHikingSchedule } from '../@services/hikingSchedule.service';
import {
  deleteHikingScheduleResult,
  getHikingScheduleResults,
} from '../@services/hikingScheduleResults.service';
import { IHikingScheduleItem } from '../@types/hiking.baseTypes';
import { HikingAccessGroup } from '../@types/hiking.rules';
import { IHikingData } from '../@types/hiking.types';
import { IHikingScheduleResult } from '../@types/hikingScheduleResults.types';
import { showScheduleEditModal } from './components/ScheduleEditModal/scheduleModalHelper';
import ScheduleItem from './components/ScheduleItem';
import { getEmptyScheduleResult } from '../@mappers/hikingScheduleResults.mapper';
import { showScheduleResultEditModal } from './components/ScheduleResultEditModal/scheduleResultModalHelper';
import { showScheduleResultPreviewModal } from './components/ScheduleResultPreviewModal/scheduleResultModalHelper';
import ScheduleResultStatus from './components/ScheduleResultStatus';
type ResultsRecords = Record<number, IHikingScheduleResult[]>;

const timeGap = 60 * 60 * 1000;

const HikingSchedulePage = ({ id_hiking }: { id_hiking: number }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData>();
  const [scheduleItems, setScheduleItems] = React.useState<IHikingScheduleItem[]>([]);
  const [scheduleResults, setScheduleResults] = React.useState<ResultsRecords>({});
  const [accessGroup, setAccessGroup] = React.useState<HikingAccessGroup>(
    HikingAccessGroup.Readonly,
  );
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const lastDateRef = React.useRef<Date | null>(null);

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);
        const hd = await getHikingDataAsync(id_hiking);
        setHikingData(hd);

        const r1 = await getHikingSchedule(id_hiking);
        setScheduleItems(r1);

        const r2 = await getHikingScheduleResults(id_hiking);
        setScheduleResults(
          r2.reduce<ResultsRecords>((acc, x) => {
            if (!acc[x.id_hiking_schedule]) acc[x.id_hiking_schedule] = [];
            acc[x.id_hiking_schedule].push(x);
            return acc;
          }, {}),
        );

        const ag = await getHikingAccessGroupAsync(id_hiking);
        setAccessGroup(ag);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [id_hiking]);

  const canEdit = React.useMemo(() => {
    const groupsWithAccess = [
      HikingAccessGroup.Time,
      HikingAccessGroup.Full,
      HikingAccessGroup.Time,
      HikingAccessGroup.Boss,
    ];
    return groupsWithAccess.includes(accessGroup);
  }, [accessGroup]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!hikingData) {
    return <PohAlert variant={AlertVariant.Danger}>Has no hikingData</PohAlert>;
  }

  const handleAdd = (sh: Partial<IHikingScheduleItem> = {}) => {
    if (!hikingData) return;
    if (!canEdit) return notificationHelper.error('Has no access');
    showScheduleEditModal({
      scheduleItem: getEmptyScheduleItem(sh),
      hikingData,
      onSave: (up) => {
        lastDateRef.current = up.finish;
        setScheduleItems((cur) => {
          const exist = cur.find((x) => x.id === up.id);
          if (exist) {
            return cur
              .map((d) => (d.id === up.id ? up : d))
              .sort((a, b) => (a.start > b.start ? 1 : -1));
          } else {
            return [...cur, up].sort((a, b) => (a.start > b.start ? 1 : -1));
          }
        });
      },
    });
  };

  let lastDate = '';

  const promptTimeGap = (): number => {
    const res = prompt('Продолжительность в минутах', (timeGap / 1000 / 60).toString()) ?? '60';
    return parseInt(res) * 60 * 1000;
  };
  return (
    <>
      <PohBreadcrumbs
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/schedule`, text: 'План похода', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={`План похода "${hikingData.name}"`}>
          {canEdit && (
            <PohButton
              size={ButtonSize.Small}
              onClick={() => handleAdd()}
              variant={ButtonVariant.Success}
            >
              Добавить
            </PohButton>
          )}
        </PageHeader>

        <section>
          {scheduleItems.map((scheduleItem, index) => {
            const timezoneForStart = hikingData?.timezones?.find(
              (tz) => tz.date_in <= scheduleItem.start && tz.date_out >= scheduleItem.start,
            );
            const timezoneForFinish = hikingData?.timezones?.find(
              (tz) => tz.date_in <= scheduleItem.finish && tz.date_out >= scheduleItem.finish,
            );

            const needHeader = lastDate !== scheduleItem.start.toLocaleDateString();
            lastDate = scheduleItem.start.toLocaleDateString();

            const itemMenu: { [buttonText: string]: (e: React.MouseEvent) => void } = {
              Редактировать: () =>
                showScheduleEditModal({
                  hikingData,
                  scheduleItem,
                  onSave: (up) => {
                    lastDateRef.current = up.finish;
                    setScheduleItems((cur) => {
                      return cur
                        .map((d) => (d.id === up.id ? up : d))
                        .sort((a, b) => (a.start > b.start ? 1 : -1));
                    });
                  },
                }),
              'Добавить до': (e) =>
                handleAdd({
                  start: new Date(
                    scheduleItem.start.getTime() - (e.shiftKey ? promptTimeGap() : timeGap),
                  ),
                  finish: scheduleItem.start,
                }),
              'Добавить после': (e) =>
                handleAdd({
                  start: scheduleItem.finish,
                  finish: new Date(
                    scheduleItem.finish.getTime() + (e.shiftKey ? promptTimeGap() : timeGap),
                  ),
                }),

              'Добавить результат': () => {
                const res = getEmptyScheduleResult(scheduleItem.id, {});

                showScheduleResultEditModal({
                  title: `Результат для "${scheduleItem.name}"`,
                  scheduleResult: res,
                  onSave: (up) =>
                    setScheduleResults((cur) => {
                      const arr = cur[scheduleItem.id] ?? [];
                      return {
                        ...cur,
                        [scheduleItem.id]:
                          res.id > 0 ? arr.map((x) => (x.id === up.id ? up : x)) : [...arr, up],
                      };
                    }),
                });
              },

              Удалить: () => {
                if (confirm(`Удалить ${scheduleItem.name} из плана?`)) {
                  deleteHikingSchedule(hikingData.id, scheduleItem.id)
                    .then(() => {
                      setScheduleItems((cur) => cur.filter((x) => x.id !== scheduleItem.id));
                      notificationHelper.success('Удалено!');
                    })
                    .catch(notificationHelper.error);
                }
              },
            };

            return (
              <React.Fragment key={scheduleItem.id}>
                {needHeader && (
                  <h4>
                    {scheduleItem.start.toLocaleDateString('default', {
                      day: 'numeric',
                      month: 'long',
                      year: 'numeric',
                      weekday: 'long',
                    })}
                  </h4>
                )}
                <ScheduleItem
                  id_hiking={hikingData!.id!}
                  scheduleItem={scheduleItem}
                  timezoneForStart={timezoneForStart}
                  timezoneForFinish={timezoneForFinish}
                  className={clsx(
                    index % 2 === 0 && 'bg-light',
                    index === scheduleItems.length - 1 && 'border-bottom mb-3',
                  )}
                  onDoubleClick={() => {
                    showScheduleEditModal({
                      hikingData,
                      scheduleItem,
                      onSave: (up) => {
                        lastDateRef.current = up.finish;
                        setScheduleItems((cur) => {
                          return cur
                            .map((d) => (d.id === up.id ? up : d))
                            .sort((a, b) => (a.start > b.start ? 1 : -1));
                        });
                      },
                    });
                  }}
                  toolbar={
                    canEdit && (
                      <PohDropdown
                        className="me-n2"
                        onClick={(e) => e.stopPropagation()}
                        menu={Object.entries(itemMenu).map(([label, callback]) => {
                          return (
                            <button
                              key={`bottom-level-menu-item-${label}`}
                              className="dropdown-item"
                              onClick={callback}
                              type="button"
                            >
                              {label}
                            </button>
                          );
                        })}
                      >
                        <PohButton size={ButtonSize.Small} icon={true}>
                          <ThreeDotsVertical />
                        </PohButton>
                      </PohDropdown>
                    )
                  }
                />
                {scheduleResults[scheduleItem.id] &&
                  scheduleResults[scheduleItem.id].length > 0 && (
                    <div className="ps-3">
                      <PohList
                        flush
                        data={scheduleResults[scheduleItem.id].map((resultItem) => {
                          const resultItemMenu: {
                            [buttonText: string]: (e: React.MouseEvent) => void;
                          } = {
                            Редактировать: () => {
                              showScheduleResultEditModal({
                                title: `Результат для "${scheduleItem.name}"`,
                                scheduleResult: resultItem,
                                onSave: (up) =>
                                  setScheduleResults((cur) => {
                                    const arr = cur[scheduleItem.id] ?? [];
                                    return {
                                      ...cur,
                                      [scheduleItem.id]: arr.map((x) => (x.id === up.id ? up : x)),
                                    };
                                  }),
                              });
                            },

                            Удалить: () => {
                              if (confirm(`Удалить ${resultItem.name} из результатов?`)) {
                                deleteHikingScheduleResult(resultItem.id)
                                  .then(() => {
                                    (setScheduleResults((cur) => {
                                      const arr = cur[scheduleItem.id] ?? [];
                                      return {
                                        ...cur,
                                        [scheduleItem.id]: arr.filter(
                                          (x) => x.id !== resultItem.id,
                                        ),
                                      };
                                    }),
                                      notificationHelper.success('Удалено!'));
                                  })
                                  .catch(notificationHelper.error);
                              }
                            },
                          };

                          return {
                            key: resultItem.id,
                            children: (
                              <div className="d-flex" style={{ gap: 12 }}>
                                {(resultItem.d1 || resultItem.d2) && (
                                  <small style={{ lineHeight: 0.9 }}>
                                    {resultItem.d1?.toLocaleTimeString('default', {
                                      timeStyle: 'short',
                                    })}
                                    <br />
                                    {resultItem.d2?.toLocaleTimeString('default', {
                                      timeStyle: 'short',
                                    })}
                                  </small>
                                )}
                                <div className="flex-grow-1" style={{ lineHeight: 0.9 }}>
                                  <strong className="d-block">{resultItem.name}</strong>
                                  <small className="text-ellipsis text-nowrap">
                                    <em>{resultItem.text}</em>
                                  </small>
                                </div>
                                <ScheduleResultStatus
                                  status={resultItem.status}
                                  onClick={() => {
                                    showScheduleResultPreviewModal({
                                      scheduleItem,
                                      scheduleResult: resultItem,
                                    });
                                  }}
                                />
                                {canEdit && (
                                  <PohDropdown
                                    className="me-n3"
                                    onClick={(e) => e.stopPropagation()}
                                    menu={Object.entries(resultItemMenu).map(
                                      ([label, callback]) => {
                                        return (
                                          <button
                                            key={`bottom-level-menu-item-${label}`}
                                            className="dropdown-item"
                                            onClick={callback}
                                            type="button"
                                          >
                                            {label}
                                          </button>
                                        );
                                      },
                                    )}
                                  >
                                    <PohButton size={ButtonSize.Small} icon={true}>
                                      <ThreeDotsVertical />
                                    </PohButton>
                                  </PohDropdown>
                                )}
                              </div>
                            ),
                          };
                        })}
                      />
                    </div>
                  )}
              </React.Fragment>
            );
          })}
        </section>
      </PohContainer>
    </>
  );
};

export default HikingSchedulePage;
