import React from 'react';

import clsx from 'clsx';

import {
  addHikingScheduleResult,
  updateHikingScheduleResult,
} from '@apps/Hiking/@services/hikingScheduleResults.service';
import { HikingScheduleResultStatus } from '@apps/Hiking/@types/DTO/hikingScheduleResults.dto.types';
import { IHikingScheduleResult } from '@apps/Hiking/@types/hikingScheduleResults.types';
import { getInputDate } from '@helpers/dateHelper';
import { err } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import PohSelect from '@ui-kit/Select';

import { hikingScheduleResultStatusNames } from '../ScheduleResultStatus';

export interface IScheduleEditModalProps {
  scheduleResult: IHikingScheduleResult;
  onSave: (up: IHikingScheduleResult) => void;
}

const ScheduleResultEditModal: React.FC<IScheduleEditModalProps> = ({ scheduleResult, onSave }) => {
  const [data, setData] = React.useState<IHikingScheduleResult>(scheduleResult);
  const [saveLoading, setSaveLoading] = React.useState(false);

  function handleChange<k extends keyof IHikingScheduleResult>(fieldName: k) {
    return (value: IHikingScheduleResult[k]) => setData((cur) => ({ ...cur, [fieldName]: value }));
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSaveLoading(true);

    try {
      if (data.id > 0) {
        await updateHikingScheduleResult(data).then(onSave);
      } else {
        await addHikingScheduleResult(data).then(onSave);
      }
    } catch (err1) {
      err(err1 as Error);
    } finally {
      setSaveLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className={clsx('d-flex flex-column')} style={{ gap: 12 }}>
      <PohRow>
        <PohCol sm={6}>
          <PohInput
            type={InputTypes.datetimeLocal}
            defaultValue={data.d1 ? getInputDate(data.d1) : ''}
            onRealChange={(v) => handleChange('d1')(new Date(v))}
            name="dateStart"
            label="Начало"
            className="w-100"
            disabled={saveLoading}
          />
        </PohCol>
        <PohCol sm={6}>
          <PohInput
            type={InputTypes.datetimeLocal}
            defaultValue={data.d2 ? getInputDate(data.d2) : ''}
            onRealChange={(v) => handleChange('d2')(new Date(v))}
            name="dateStart"
            label="Конец"
            className="w-100"
            disabled={saveLoading}
          />
        </PohCol>
      </PohRow>
      <PohInput
        label="Название"
        value={data.name}
        onChange={handleChange('name')}
        autoComplete="data-name"
        name="name"
        className="w-100"
        disabled={saveLoading}
      />

      <PohSelect<HikingScheduleResultStatus>
        required
        label="Статус"
        value={data.status}
        onChange={handleChange('status')}
        options={Object.keys(HikingScheduleResultStatus).map((x) => {
          return {
            label: hikingScheduleResultStatusNames[x as HikingScheduleResultStatus],
            value: x as unknown as HikingScheduleResultStatus,
          };
        })}
        className="w-100"
        disabled={saveLoading}
      />

      <PohInput
        type={InputTypes.textarea}
        label="Описание"
        placeholder="Markdown supported"
        value={data.text}
        onChange={handleChange('text')}
        autoComplete="data-name"
        name="name"
        className="w-100"
        disabled={saveLoading}
      />

      <footer className="d-flex justify-content-between pt-3 align-items-center mb-n3 pt-3">
        <aside className="flex-grow-1">&nbsp;</aside>
        <PohButton type="submit" variant={ButtonVariant.Primary} disabled={saveLoading}>
          {data.id > 0 ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
};

export default ScheduleResultEditModal;
